    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Logarithmic transformation of DIFF to emphasize safety
    if DIFF > 0:
        diff_transform = max(0, math.log(DIFF + 1))
    else:
        diff_transform = max(0, math.log(1e10 - DIFF + 1))

    # Quadratic weighting of RI
    ri_weight = math.exp(-RI ** 2 / 100)

    # Nonlinear combination of space metrics based on inverse of SH * EMP
    if SH * EMP == 0:
        space_metric = 0.0
    else:
        space_metric = 1 / (SH * EMP + 1) * 0.1

    # Combine metrics with adjusted weights
    priority = space_metric * 0.2 + ri_weight * 0.3 + diff_transform * 0.5
    return priority

